KG42.register("rules-ae0b01b221c27740c434dbb6",{"id":"25-p2p_ancillary_bidding::v141-c-R001","paper":"25-p2p_ancillary_bidding","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01-p2p-cda","name":"Demand submission","process_stage":"bidding","market_meaning":"Updating a partially matched demand bid is conditional on the local allocation outcome: its remaining requested quantity becomes σ'_{b,t} = σ_{b,t} - σ_{s,t}. Scope: Residual demand-bid updates in the CDA order book for time slot t during the corresponding Agreement Period. Condition: The demand bid is not fully matched and σ_{b,t} - σ_{s,t} > 0. A submitted demand bid is removed from the order book when local allocation has fully matched it. Scope: Removal of completed demand bids from the CDA order book for time slot t. Condition: The demand bid is fully matched. A customer with positive optimized net load submits a demand bid with the electricity amount to be bought equal to NL_{i,t}^*. Scope: Community customers submitting demand bids during the CDA Agreement Period corresponding to time slot t in Target Time Period T. Condition: NL_{i,t}^* > 0.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.local"],"E":[{"edge_id":"v141-c-R001-E001","source":"bidding.demand","target":"clearing.local","type":"conditional_on","constraint_ids":["v141-c-R001-C001","v141-c-R001-C002"],"evidence_ids":["v141-b-g01-E09","v141-b-g04-E03"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Community customers submitting demand bids during the CDA Agreement Period corresponding to time slot t in Target Time Period T. | Removal of completed demand bids from the CDA order book for time slot t. | Residual demand-bid updates in the CDA order book for time slot t during the corresponding Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E04","v141-b-g01-E09","v141-b-g01-E14","v141-b-g04-E03"]},"x":[{"variable_id":"v141-c-R001-X001","symbol":"σ_{b,t}","meaning":"Electricity quantity requested by the demand bid o_{b,t} for time slot t, as defined in the order descriptor.","kind":"operational","domain":"kWh amount of electricity requested in a submitted demand bid; the source gives no explicit numeric bound on the supplied pages","unit":"kWh","indices":["b","t"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E09","v141-b-g04-E03"]},{"variable_id":"v141-c-R001-X002","symbol":"σ'_{b,t}","meaning":"Remaining requested quantity of a partially matched demand bid after local allocation for time slot t.","kind":"operational","domain":"kWh residual demand quantity produced by the order-book update; the source gives no explicit numeric bound","unit":"kWh","indices":["b","t"],"evidence_ids":["v141-b-g01-E09","v141-b-g04-E03"]}],"theta":[{"parameter_id":"v141-c-R001-T001","symbol":"σ_{s,t}","meaning":"Electricity quantity of the matched seller ask o_{s,t} used in the demand-bid residual update for time slot t; for this demand-submission rule it is the clearing-side ask quantity entering the update condition.","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic ask-order quantity; no numeric value is supplied in the source"},"unit":"kWh","indices":["s","t"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E09","v141-b-g04-E03"]},{"parameter_id":"v141-c-R001-T002","symbol":"NL_{i,t}^*","meaning":"Optimized net load of customer i at time slot t obtained from the customer's operational scheduling problem, used to size a demand bid when positive.","value":{"kind":"symbolic","number_value":null,"text_value":"optimized net-load value from the scheduling problem; its sign selects bid or ask submission, with no numeric value supplied"},"unit":"kW (source unit for NL_{i,t}; the source does not reconcile this with the kWh bid-amount unit)","indices":["i","t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E14","v141-b-g02-E01-cda-bid-ask-amount"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"logical","role":"core","statement":"Updating a partially matched demand bid is conditional on the local allocation outcome: its remaining requested quantity becomes σ'_{b,t} = σ_{b,t} - σ_{s,t}. Scope: Residual demand-bid updates in the CDA order book for time slot t during the corresponding Agreement Period. Condition: The demand bid is not fully matched and σ_{b,t} - σ_{s,t} > 0.","expression":"σ'_{b,t} = σ_{b,t} − σ_{s,t} if σ_{b,t} − σ_{s,t} > 0","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["v141-c-R001-X001","v141-c-R001-X002"],"parameter_refs":["v141-c-R001-T001"],"evidence_ids":["v141-b-g01-E09","v141-b-g04-E03"]},{"constraint_id":"v141-c-R001-C002","kind":"logical","role":"core","statement":"A submitted demand bid is removed from the order book when local allocation has fully matched it. Scope: Removal of completed demand bids from the CDA order book for time slot t. Condition: The demand bid is fully matched.","expression":"σ_{b,t} ≤ σ_{s,t} ⇒ the demand order for (b,t) is removed from the order book for time slot t","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["v141-c-R001-X001"],"parameter_refs":["v141-c-R001-T001"],"evidence_ids":["v141-b-g01-E09","v141-b-g04-E03"]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"A customer with positive optimized net load submits a demand bid with the electricity amount to be bought equal to NL_{i,t}^*. Scope: Community customers submitting demand bids during the CDA Agreement Period corresponding to time slot t in Target Time Period T. Condition: NL_{i,t}^* > 0.","expression":"NL_{i,t}^* > 0 ⇒ σ_{b,t} = NL_{i,t}^*","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["v141-c-R001-X001"],"parameter_refs":["v141-c-R001-T002"],"evidence_ids":["v141-b-g01-E04","v141-b-g01-E14","v141-b-g01-E13"]}],"pi":[{"evidence_id":"v141-b-g01-E04","location":{"location_id":"src-212077b9a1-p04-c1r2__v141-a-M01-participation","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 2. The timeline for ancillary service provision As presented in Section 2, customers trade ener","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"As presented in Section 2, customers trade energy with each other to reach P2P energy trading agreements by participating in the CDA mechanism. For any time slot t in the Target Time Period T, in the corresponding Agreement Period of CDA, customers submit bids or asks according to their roles being ‘buyers’ (who have electricity deficit at t) or ‘sellers’ (who have electricity surplus at t)."},{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-212077b9a1-p04-c1r4__v141-a-M01-matching","page":4,"printed_page":null,"section":null,"anchor_text":"The bid/ask that is fully matched will be removed from the order pr book, and the bid/ask that is no","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"The bid/ask that is fully matched will be removed from the order book, and the bid/ask that is not fully matched will be updated by o'_{b,t} = (b_t, π_{b,t}, σ'_{b,t}, τ_{b,t}) if σ_{b,t} - σ_{s,t} > 0, (4) o'_{s,t} = (s_t, π_{s,t}, σ'_{s,t}, τ_{s,t}) if σ_{b,t} - σ_{s,t} \u003c 0, (5) where σ'_{b,t} = σ_{b,t} - σ_{s,t}, (6) σ'_{s,t} = σ_{s,t} - σ_{b,t}. (7)"},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-212077b9a1-p04-c2r4__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"p , p er premise and j is the device index. Equations (10) and (11) are the equality and inequality ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"As proposed in [40], the customers decide the amount of electricity to be sold/bought in the P2P energy trading mechanism based on their net load profiles. For any time slot t, a customer will submit a bid with the amount of electricity to be bought being NL_{i,t}^*, if NL_{i,t}^* > 0. Similarly, the customer will submit an ask with the amount of electricity to be sold being |NL_{i,t}^*|, if NL_{i,t}^* \u003c 0."},{"evidence_id":"v141-b-g04-E03","location":{"location_id":"src-212077b9a1-p15-c1r1__v141-a-M01-matching","page":15,"printed_page":null,"section":"Appendix A","anchor_text":"Y. Zhou et al. (continued) CDA process for customers to reach P2P energy trading agre 7: make the tr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-15.png","occurrence_role":"formula"},"source_text":"8: if σ_{b,t} > σ_{s,t}\n9: modify the bid as o'_{b,t} = o_{b,t}(b_t, π_{b,t}, σ'_{b,t}, τ_{b,t}) where σ'_{b,t} = σ_{b,t} - σ_{s,t};\n10: remove the ask o_{s,t} from the order book;\n11: else\n12: modify the ask as o'_{s,t} = o_{s,t}(b_t, π_{s,t}, σ'_{s,t}, τ_{s,t}) where σ'_{s,t} = σ_{s,t} - σ_{b,t};\n13: remove the bid o_{b,t} from the order book;\n14: end if\n15: end if\n16: end for\n17: end if\n18: end while"},{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-212077b9a1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 2. The timeline for ancillary service provision As presented in Section 2, customers trade ener","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A bid, which is submitted by a buyer, is represented by o_{b,t}(b_t, π_{b,t}, σ_{b,t}, τ_{b,t}), which means that the buyer b_t would like to by the σ_{b,t} (kWh) amount of electricity at the price π_{b,t} (£/kWh), and the bid arrives at the ‘exchange’ at the time τ_{b,t}. Note that the exchange is a centralized or decentralized platform set for P2P energy trading within the community. Similarly, an ask, which is submitted by a seller is represented by o_{s,t}(s_t, π_{s,t}, σ_{s,t}, τ_{s,t})."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-212077b9a1-p04-c2r4__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"p , p er premise and j is the device index. Equations (10) and (11) are the equality and inequality ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"By solving the optimization problem, each customer (usually through home energy management systems), indexed by i, is able to obtain the operational schedules, and thus obtain the net load profile throughout the Target Time Period T, denoted as NL_i^* = {NL_{i,t}^* | t = 1,2,…,T} where NL_{i,t}^* > 0 represents that the premise imports electricity from the power utility while NL_{i,t}^* \u003c 0 represents that the premise exports surplus generation to the power utility."},{"evidence_id":"v141-b-g02-E01-cda-bid-ask-amount","location":{"location_id":"src-212077b9a1-p05-c1r1__v141-a-M01-bidding","page":5,"printed_page":null,"section":null,"anchor_text":"Y. Zhou et al. > 0. Similarly, tothe amount of electricity to be bought being NL*i,t, if NL*i,t the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"the amount of electricity to be bought being \\(NL^*_{i,t}\\), if \\(NL^*_{i,t} > 0\\). Similarly, the customer will submit an ask with the amount of electricity to be sold being \\(|NL^*_{i,t}|\\), if \\(NL^*_{i,t} \u003c 0\\)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-matching","v141-a-M01-participation"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E09","quote":"the bid/ask that is not fully matched will be updated by o'_{b,t} = (b_t, π_{b,t}, σ'_{b,t}, τ_{b,t}) if σ_{b,t} - σ_{s,t} > 0, (4)"},{"evidence_id":"v141-b-g04-E03","quote":"8: if σ_{b,t} > σ_{s,t}\n9: modify the bid as o'_{b,t} = o_{b,t}(b_t, π_{b,t}, σ'_{b,t}, τ_{b,t}) where σ'_{b,t} = σ_{b,t} - σ_{s,t};"}],[{"evidence_id":"v141-b-g01-E09","quote":"The bid/ask that is fully matched will be removed from the order book"}],[{"evidence_id":"v141-b-g01-E14","quote":"For any time slot t, a customer will submit a bid with the amount of electricity to be bought being NL_{i,t}^*, if NL_{i,t}^* > 0."},{"evidence_id":"v141-b-g01-E04","quote":"For any time slot t in the Target Time Period T, in the corresponding Agreement Period of CDA, customers submit bids or asks according to their roles being ‘buyers’ (who have electricity deficit at t) or ‘sellers’ (who have electricity surplus at t)."}]],"C2_formalization":{"graph_sha256":"f3add0ec78874e5c487ea03405e899d8e0718405bc7c4782aec8fc3577376092","applicability":"formalized","reason":"The frozen rule contains explicit CDA demand-order update, fully-matched removal, and positive-net-load bid-amount statements. C001 and C003 are formalized directly; C002 is formalized as the source-stated complementary removal branch. The B evidence used here is provisionally eligible but remains unreviewed; no claim of independent source verification is made.","bindings":[{"object_id":"v141-c-R001-X001","node_ids":["bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The demand-bid quantity is the demand-submission object whose update/removal branch is conditioned on clearing.local; edge E001 records that conditional relation for C001 and C002."},{"object_id":"v141-c-R001-X002","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R001-E001"],"rationale":"The residual demand quantity is produced by the demand order update after local allocation, so it spans the demand order and local clearing nodes under frozen edge E001."},{"object_id":"v141-c-R001-T001","node_ids":["clearing.local"],"edge_ids":["v141-c-R001-E001"],"rationale":"The ask quantity σ_{s,t} is the clearing-side input used in the demand-bid residual update condition and formula; edge E001 is the existing conditional_on link between the demand and local-clearing nodes."},{"object_id":"v141-c-R001-T002","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The optimized net load is the input that determines the submitted demand-bid amount in C003; no additional frozen edge is present for C003."},{"object_id":"v141-c-R001-C001","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R001-E001"],"rationale":"C001 formalizes the conditional residual-quantity update for a partially matched demand bid, exactly one of the constraints attached to frozen edge E001."},{"object_id":"v141-c-R001-C002","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R001-E001"],"rationale":"C002 formalizes the complementary fully-matched removal branch for the demand bid; E001 lists C002 as a constrained relation between demand submission and local clearing."},{"object_id":"v141-c-R001-C003","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"C003 formalizes the positive-net-load demand-bid amount rule using only the demand-submission node; the frozen graph provides no C003-specific edge."}],"revision_requests":["B source re-extraction/audit should reconcile the source unit of NL_{i,t}^* (kW for net load) with the demand-bid amount σ_{b,t} (kWh); the present formalization transcribes the stated equality without changing either symbol or unit."]}},"quarantined_references":[]}});
